<template>
  <div class="cb-page closing-page">
    <div class="cb-container">
      <page-header title="Produtividade Líquida" :summary-items="headerSummary">
        <template #actions>
          <v-btn variant="tonal" prepend-icon="mdi-calculator-variant" :loading="calculating" :disabled="!selectedClosing || !canCalculate" @click="calculate">
            Recalcular
          </v-btn>
          <v-btn color="primary" prepend-icon="mdi-send-outline" disabled>Enviar para decisão</v-btn>
        </template>
      </page-header>

      <section class="closing-toolbar cb-card">
        <v-select v-model="selectedId" :items="closingOptions" item-title="title" item-value="value" label="Competência e escopo" hide-details />
        <div v-if="selectedClosing" class="closing-toolbar__badges">
          <v-chip size="small" color="info" variant="tonal">Versão {{ selectedClosing.currentVersion.versionNumber }}</v-chip>
          <v-chip size="small" :color="selectedClosing.workflowStatus === 'DRAFT' ? 'warning' : 'success'" variant="tonal">{{ workflowLabel }}</v-chip>
          <v-chip v-if="!selectedClosing.currentVersion.calculationCurrent" size="small" color="error" variant="tonal">Cálculo obsoleto</v-chip>
        </div>
      </section>

      <alert-strip v-if="errorMessage" variant="info" :description="errorMessage" />
      <div v-if="loading" class="cb-empty-state"><v-progress-circular indeterminate /><p>Carregando apuração…</p></div>
      <div v-else-if="!selectedClosing" class="cb-empty-state">
        <v-icon size="44">mdi-table-large</v-icon><p class="cb-empty-state__title">Nenhuma apuração encontrada</p>
        <p>Crie a competência pelo contrato de importação para visualizar a matriz.</p>
      </div>

      <template v-else>
        <section v-if="summary && matrix" class="closing-kpis">
          <article class="cb-card metric"><span>Total bruto</span><strong>{{ money(summary.grossAmount) }}</strong></article>
          <article class="cb-card metric"><span>Deduções e retenções</span><strong class="negative">{{ money(summary.deductionAmount) }}</strong></article>
          <article class="cb-card metric"><span>Ajustes do fechamento</span><strong>{{ signedMoney(summary.closingAdjustmentAmount) }}</strong></article>
          <article class="cb-card metric metric--primary"><span>Produtividade Líquida</span><strong>{{ money(summary.productivityAmount) }}</strong></article>
          <article class="cb-card metric metric--pool"><span>Margem de Contribuição</span><strong>{{ money(summary.undistributedPoolAmount) }}</strong><small>Pool sem destinação</small></article>
          <article class="cb-card metric"><span>Receita líquida apurada</span><strong>{{ money(summary.netRevenueAmount) }}</strong></article>
        </section>

        <section v-if="userStore.canWrite && selectedClosing.workflowStatus === 'DRAFT' && selectedClosing.currentVersion.versionStatus === 'EDITABLE'" class="cb-card obligations-card tabular-import" aria-labelledby="tabular-import-title">
          <div class="section-heading"><div><p class="eyebrow">Fonte tabular</p><h2 id="tabular-import-title">Importar planilha</h2></div></div>
          <p class="matrix-hint">CSV ou XLSX de uma aba. O arquivo é lido apenas nesta solicitação: a confirmação grava itens normalizados e proveniência protegida, nunca o arquivo bruto.</p>
          <div class="payment-form"><v-file-input v-model="tabularFile" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" label="Arquivo CSV ou XLSX" prepend-icon="mdi-file-table-outline" /><v-text-field v-model="tabularBatchKey" label="Chave idempotente do lote" hint="Não reutilize para outro arquivo ou mapeamento" persistent-hint /></div>
          <details class="tabular-mapping"><summary>Mapeamento explícito de colunas</summary><p class="matrix-hint">Informe exatamente os títulos presentes na primeira linha. Fonte e participante devem conter IDs canônicos já cadastrados; a importação não deduz identidade, moeda ou classificação.</p><div class="payment-form"><v-text-field v-model="tabularMapping.itemKeyColumn" label="Chave do item *" /><v-text-field v-model="tabularMapping.sourceIdColumn" label="ID da fonte *" /><v-text-field v-model="tabularMapping.amountColumn" label="Valor *" /><v-text-field v-model="tabularMapping.occurredOnColumn" label="Data *" /><v-text-field v-model="tabularMapping.attributionMethodColumn" label="Método de atribuição" /><v-text-field v-model="tabularMapping.participantIdColumn" label="ID do participante" /><v-text-field v-model="tabularMapping.poolKeyColumn" label="Chave do pool" /><v-select v-model="tabularMapping.defaultAttributionMethod" :items="[{ title: 'Atribuição direta', value: 'DIRECT_ATTRIBUTION' }, { title: 'Pool não distribuído', value: 'UNDISTRIBUTED_POOL' }]" label="Método padrão" /><v-select v-model="tabularMapping.decimalSeparator" :items="[{ title: 'Ponto (12.50)', value: 'DOT' }, { title: 'Vírgula (12,50)', value: 'COMMA' }]" label="Separador decimal *" /></div></details>
          <div class="payment-form"><v-btn variant="tonal" :disabled="!selectedTabularFile || tabularValidating" :loading="tabularValidating" @click="validateTabularImport">Validar arquivo</v-btn><v-btn v-if="userStore.isAdmin" color="primary" :disabled="!canConfirmTabularImport" :loading="tabularConfirming" @click="confirmTabularImport">Confirmar lote normalizado</v-btn></div>
          <p v-if="tabularMessage" class="matrix-hint" :class="{ 'negative': tabularValidation && !tabularValidation.valid }" role="status">{{ tabularMessage }}</p>
          <div v-if="tabularValidation" class="tabular-result"><p><strong>{{ tabularValidation.rowCount }}</strong> linha(s) · adições {{ money(tabularValidation.additionTotal) }} · reversões {{ money(tabularValidation.reversalTotal) }}</p><p v-if="!tabularValidation.detailedPreview" class="matrix-hint">A prévia detalhada exige concessão explícita de acesso a dados sensíveis. Estes totais e erros não exibem conteúdo da planilha.</p><ul v-if="tabularValidation.issues.length" class="tabular-issues" role="alert"><li v-for="issue in tabularValidation.issues" :key="`${issue.rowNumber}-${issue.code}`">Linha {{ issue.rowNumber }}<template v-if="issue.column"> · {{ issue.column }}</template>: {{ issue.message }} ({{ issue.code }})</li></ul><div v-if="tabularValidation.detailedPreview && tabularValidation.previewRows.length" class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Linha</th><th>Chave</th><th>Valor</th><th>Data</th><th>Método</th></tr></thead><tbody><tr v-for="row in tabularValidation.previewRows" :key="row.rowNumber"><th>{{ row.rowNumber }}</th><td>{{ row.clientItemKey }}</td><td>{{ money(row.amount) }}</td><td>{{ row.occurredOn || '—' }}</td><td>{{ row.attributionMethod || '—' }}</td></tr></tbody></table></div></div>
          <p v-if="!userStore.isAdmin" class="matrix-hint">A confirmação é restrita a ADMIN/OWNER com acesso explícito aos dados sensíveis do fechamento.</p>
        </section>

        <section class="cb-card obligations-card operations-center" aria-labelledby="operations-center-title">
          <div class="section-heading"><div><p class="eyebrow">Operação segura</p><h2 id="operations-center-title">Central de importações e linha do tempo</h2></div><v-btn variant="tonal" :loading="loadingOperations" @click="loadOperations">Atualizar</v-btn></div>
          <p class="matrix-hint">Mostra apenas fatos já registrados. Pagamentos internos não transferem dinheiro; conciliações não alteram saldo.</p>
          <div v-if="loadingOperations" class="cb-empty-state"><v-progress-circular indeterminate size="24" /></div>
          <template v-else>
            <div v-if="operations?.pendingActions.length" class="pending-actions" role="status"><strong>Pendências</strong><ul><li v-for="item in operations.pendingActions" :key="item.code">{{ item.label }} <small>· ação de {{ item.requiredRole }}</small></li></ul></div>
            <p v-else class="matrix-hint">Não há pendência operacional identificada para este fechamento.</p>
            <h3>Execuções de importação</h3><p v-if="!importExecutions.length" class="matrix-hint">Nenhuma importação confirmada ou validação rejeitada foi registrada.</p><div v-else class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Estado</th><th>Arquivo/origem</th><th>Versão</th><th>Autor</th><th>Aceitas</th><th>Rejeitadas</th><th>Totais</th><th>Data</th><th>Erros</th></tr></thead><tbody><tr v-for="item in importExecutions" :key="item.id"><th><v-chip size="x-small" :color="item.status === 'CONFIRMED' ? 'success' : 'error'" variant="tonal">{{ item.status === 'CONFIRMED' ? 'Confirmada' : 'Rejeitada' }}</v-chip></th><td>{{ item.format }} · planilha tabular</td><td>{{ item.versionNumber }}</td><td>{{ item.actorUserId }}</td><td>{{ item.acceptedRows }}</td><td>{{ item.rejectedRows }}</td><td>{{ money(item.additionTotal) }} / {{ money(item.reversalTotal) }}</td><td>{{ formatDateTime(item.occurredAt) }}</td><td><v-btn v-if="item.status === 'REJECTED'" size="x-small" variant="text" @click="loadImportIssues(item.id)">Consultar códigos</v-btn></td></tr></tbody></table></div>
            <p v-if="importIssues" class="matrix-hint" role="status">{{ importIssues.detailed ? 'Erros por linha autorizados:' : 'Detalhe por linha exige ADMIN/OWNER com concessão sensível.' }} {{ Object.entries(importIssues.issueCounts).map(([code,count]) => `${code}: ${count}`).join(' · ') }}</p><ul v-if="importIssues?.detailed" class="tabular-issues"><li v-for="issue in importIssues.items" :key="`${issue.rowNumber}-${issue.code}`">Linha {{ issue.rowNumber }} · {{ issue.code }}: {{ issue.message }}</li></ul>
            <h3>Linha do tempo</h3><ol v-if="operations?.timeline.length" class="operations-timeline"><li v-for="item in operations.timeline" :key="`${item.type}-${item.occurredAt}`"><strong>{{ item.title }}</strong><span>{{ item.description }}</span><small>{{ formatDateTime(item.occurredAt) }} · {{ item.status }}</small></li></ol><p v-else class="matrix-hint">Ainda não há fatos do fechamento para exibir.</p>
          </template>
        </section>

        <section v-if="summary && matrix" class="cb-card obligations-card decision-workflow" aria-labelledby="decision-workflow-title">
          <div class="section-heading"><div><p class="eyebrow">Decisão colaborativa</p><h2 id="decision-workflow-title">Produtividade Líquida</h2></div><v-btn variant="tonal" :loading="loadingDecisionData" @click="loadDecisionData">Atualizar decisões</v-btn></div>
          <p class="matrix-hint">A proposta usa exclusivamente a execução de cálculo atual. Submeter bloqueia a revisão; aprovar emite obrigações de produtividade de forma atômica.</p>
          <div v-if="selectedClosing.workflowStatus === 'DRAFT'" class="payment-form"><v-text-field v-model="payoutDueDate" label="Vencimento padrão (opcional)" type="date" /><v-btn color="primary" :disabled="!selectedClosing.currentVersion.calculationCurrent" :loading="creatingPayout" @click="createPayoutDecision">Criar proposta de repasse</v-btn></div>
          <div v-if="payoutDecision" class="decision-card"><p><strong>{{ decisionStatusLabel(payoutDecision.status) }}</strong> · revisão {{ payoutDecision.revision }} · {{ money(payoutDecision.productivityAmount) }} · {{ payoutDecision.lines.length }} participante(s)</p><div class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Participante</th><th>Valor</th><th>Vencimento</th></tr></thead><tbody><tr v-for="line in payoutDecision.lines" :key="line.id"><th>{{ line.participantId }}</th><td>{{ money(line.amount) }}</td><td>{{ line.dueDate || '—' }}</td></tr></tbody></table></div><div class="payment-form"><v-btn v-if="payoutDecision.status === 'DRAFT' && userStore.canWrite" @click="submitPayoutDecision">Enviar para revisão</v-btn><v-textarea v-if="payoutDecision.status === 'REVIEW' && userStore.isAdmin" v-model="payoutApprovalJustification" label="Justificativa da aprovação" /><v-btn v-if="payoutDecision.status === 'REVIEW' && userStore.isAdmin" color="success" :disabled="!payoutApprovalJustification.trim()" @click="approvePayoutDecision">Aprovar e emitir obrigações</v-btn></div></div>
          <p v-else class="matrix-hint">Nenhuma proposta carregada. Consulte as decisões existentes ou crie uma proposta a partir do cálculo atual.</p>
          <details v-if="calculationRevisions.length" class="tabular-mapping"><summary>Comparar revisões de cálculo</summary><div class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Revisão</th><th>Status</th><th>Bruto</th><th>Produtividade</th><th>Margem</th><th>Receita líquida</th><th>Calculada em</th></tr></thead><tbody><tr v-for="revision in calculationRevisions" :key="revision.calculationRunId"><th>{{ revision.inputRevision }}</th><td>{{ revision.runStatus === 'CURRENT' ? 'Atual' : 'Obsoleta' }}</td><td>{{ money(revision.grossAmount) }}</td><td>{{ money(revision.productivityAmount) }}</td><td>{{ money(revision.undistributedPoolAmount) }}</td><td>{{ money(revision.netRevenueAmount) }}</td><td>{{ formatDateTime(revision.calculatedAt) }}</td></tr></tbody></table></div></details>
        </section>

        <section v-if="summary && matrix && selectedClosing.workflowStatus === 'APPROVED'" class="cb-card obligations-card decision-workflow" aria-labelledby="margin-workflow-title">
          <div class="section-heading"><div><p class="eyebrow">Destinação independente</p><h2 id="margin-workflow-title">Margem de Contribuição</h2></div><v-btn variant="tonal" :loading="loadingDecisionData" @click="loadDecisionData">Atualizar decisões</v-btn></div>
          <p class="matrix-hint">Retenção e reserva alocam margem sem pagamento. Compromisso de despesa e distribuição somente emitem obrigações quando a decisão é aprovada.</p>
          <div class="payment-form"><v-text-field v-model="marginPoolKey" label="Pool" /><v-select v-model="marginAllocationType" :items="marginAllocationTypes" label="Destinação" /><v-text-field v-model.number="marginAmount" label="Valor" type="number" min="0.01" /><v-text-field v-model="marginPurpose" label="Finalidade" /><v-text-field v-if="marginNeedsBeneficiary" v-model="marginBeneficiaryName" label="Beneficiário/credor" /><v-text-field v-if="marginAllocationType === 'DISTRIBUTE'" v-model="marginParticipantId" label="ID do participante destinatário" /><v-btn color="primary" :disabled="!canCreateMarginDecision" @click="createMarginDecision">Criar proposta de margem</v-btn></div>
          <div v-for="decision in marginDecisions" :key="decision.id" class="decision-card"><p><strong>{{ decisionStatusLabel(decision.status) }}</strong> · revisão {{ decision.revision }} · alocado {{ money(decision.allocatedAmount) }} · disponível {{ money(decision.unallocatedMargin) }}</p><ul><li v-for="line in decision.allocations" :key="line.id">{{ marginTypeLabel(line.type) }} · {{ money(line.amount) }} · {{ line.purpose }}<template v-if="line.beneficiaryDisplayName"> · {{ line.beneficiaryDisplayName }}</template></li></ul><div class="payment-form"><v-btn v-if="decision.status === 'DRAFT' && userStore.canWrite" @click="submitMarginDecision(decision)">Enviar para revisão</v-btn><v-textarea v-if="decision.status === 'REVIEW' && userStore.isAdmin" v-model="marginApprovalJustification" label="Justificativa da aprovação" /><v-btn v-if="decision.status === 'REVIEW' && userStore.isAdmin" color="success" :disabled="!marginApprovalJustification.trim()" @click="approveMarginDecision(decision)">Aprovar destinação</v-btn></div></div>
        </section>

        <section v-if="summary && matrix" class="cb-card matrix-card">
          <div class="section-heading"><div><p class="eyebrow">Participante × origem</p><h2>Composição da Produtividade Líquida</h2></div><span>Valores em {{ selectedClosing.currency }}</span></div>
          <div class="matrix-scroll">
            <table class="closing-matrix">
              <thead><tr><th>Participante</th><th v-for="source in matrix.sources" :key="source.id">{{ source.displayName }}</th><th>Total líquido</th></tr></thead>
              <tbody>
                <tr v-for="row in matrix.rows" :key="row.participant.id">
                  <th>{{ row.participant.displayName }}</th>
                  <td v-for="source in matrix.sources" :key="source.id">
                    <button class="cell-button" :disabled="!row.values[source.id]" @click="openDrillDown(row, source)">{{ money(row.values[source.id] || 0) }}</button>
                  </td>
                  <td class="row-total">{{ money(row.total) }}</td>
                </tr>
              </tbody>
              <tfoot><tr><th>Total por origem</th><td v-for="source in matrix.sources" :key="source.id">{{ money(matrix.sourceTotals[source.id] || 0) }}</td><td>{{ money(matrix.productivityTotal) }}</td></tr></tfoot>
            </table>
          </div>
          <p class="matrix-hint"><v-icon size="16">mdi-cursor-default-click-outline</v-icon> Selecione um valor para conferir os itens que formam a célula.</p>
        </section>

        <section v-if="summary && matrix" class="closing-lower-grid">
          <article class="cb-card reconciliation-card">
            <div class="section-heading"><div><p class="eyebrow">Conciliação de entrada</p><h2>Cobertura bancária</h2></div><strong>{{ summary.reconciliation.coveragePercentage.toFixed(1) }}%</strong></div>
            <v-progress-linear :model-value="summary.reconciliation.coveragePercentage" color="primary" height="8" rounded />
            <dl><div><dt>Entrada esperada</dt><dd>{{ money(summary.reconciliation.expectedInflowAmount) }}</dd></div><div><dt>Entrada encontrada</dt><dd>{{ money(summary.reconciliation.reconciledInflowAmount) }}</dd></div><div><dt>Divergência</dt><dd>{{ money(summary.reconciliation.divergenceAmount) }}</dd></div><div><dt>Itens não conciliados</dt><dd>{{ summary.reconciliation.unreconciledItemCount }}</dd></div></dl>
            <p>A conciliação confirma recebimentos e não altera a titularidade dos valores.</p>
          </article>
          <article class="cb-card memory-card">
            <div class="section-heading"><div><p class="eyebrow">Explicabilidade</p><h2>Memória de cálculo</h2></div><v-btn variant="text" :loading="loadingMemory" @click="toggleMemory">{{ memory ? 'Ocultar' : 'Consultar' }}</v-btn></div>
            <p>Política {{ summary.calculationPolicyVersion }} · {{ summary.roundingMode }} · escala intermediária {{ summary.intermediateScale }}</p>
            <div v-if="memory" class="memory-list"><details v-for="item in memory.items" :key="item.itemId"><summary>{{ item.clientItemKey }}</summary><pre>{{ prettyMemory(item.memory) }}</pre></details></div>
            <div class="residual"><span>Residual explícito</span><strong>{{ money(summary.residualAmount) }}</strong></div>
          </article>
        </section>
        <section v-if="summary && matrix" class="cb-card obligations-card">
          <div class="section-heading"><div><p class="eyebrow">Settlement operacional</p><h2>Obrigações emitidas</h2></div><v-select v-model="obligationDomain" :items="[{ title: 'Todos os domínios', value: 'ALL' }, { title: 'Produtividade', value: 'PRODUCTIVITY' }, { title: 'Margem', value: 'MARGIN' }]" density="compact" hide-details /></div>
          <div v-if="loadingObligations" class="cb-empty-state"><v-progress-circular indeterminate size="24" /></div>
          <p v-else-if="!filteredObligations.length" class="matrix-hint">Nenhuma obrigação emitida para os filtros selecionados.</p>
          <div v-else class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Domínio</th><th>Principal</th><th>Pago em dinheiro</th><th>Crédito</th><th>Saldo aberto</th><th>Dinheiro</th><th>Resolução</th></tr></thead><tbody><tr v-for="item in filteredObligations" :key="item.id"><th>{{ item.domain === 'PRODUCTIVITY' ? 'Produtividade' : 'Margem' }}</th><td>{{ money(item.principalAmount) }}</td><td>{{ money(item.cashPaidAmount) }}</td><td>{{ money(item.creditedAmount) }}</td><td>{{ money(item.openAmount) }}</td><td><v-chip size="x-small" variant="tonal">{{ statusLabel(item.cashSettlementStatus) }}</v-chip></td><td><v-chip size="x-small" :color="item.resolutionStatus === 'SETTLED' ? 'success' : undefined" variant="tonal">{{ statusLabel(item.resolutionStatus) }}</v-chip></td></tr></tbody></table></div>
          <p class="matrix-hint">Consulta somente. Registrar fatos internos não executa transferência bancária.</p>
        </section>
        <section v-if="summary && matrix && userStore.canWrite" class="cb-card obligations-card manual-payment"><div class="section-heading"><div><p class="eyebrow">Registro interno</p><h2>Pagamento manual</h2></div></div><p class="matrix-hint">Este registro não realiza uma transferência bancária.</p><div class="payment-form"><v-text-field v-model.number="paymentAmount" label="Valor" type="number" min="0.01" /><v-text-field v-model="paymentReference" label="Referência interna" /><v-text-field v-model="paymentExecutedAt" label="Data e hora da ocorrência" type="datetime-local" /><v-btn color="primary" :loading="savingPayment" @click="recordPayment">Registrar como rascunho</v-btn></div><div v-if="recordedPayment"><p class="matrix-hint">Rascunho {{ recordedPayment.id }} · {{ money(recordedPayment.amount) }}</p><v-textarea v-if="userStore.isAdmin" v-model="confirmationJustification" label="Justificativa da confirmação" /><v-text-field v-if="userStore.isAdmin" v-model="confirmationEvidence" label="Evidência (não será exibida depois)" /><div class="payment-form"><v-btn v-if="userStore.isAdmin" color="success" :disabled="!confirmationJustification || !confirmationEvidence" @click="confirmPayment">Confirmar fato interno</v-btn><v-btn color="error" variant="tonal" @click="voidPayment">Anular rascunho</v-btn></div></div></section>
        <section v-if="summary && matrix && (suggestionPaymentId || bankSuggestions)" class="cb-card obligations-card bank-suggestions" aria-labelledby="bank-suggestions-title"><div class="section-heading"><div><p class="eyebrow">Conciliação bancária assistida</p><h2 id="bank-suggestions-title">Sugestões de extrato</h2></div><v-btn v-if="suggestionPaymentId" variant="tonal" :loading="loadingSuggestions" @click="loadBankSuggestions">Atualizar</v-btn></div><p class="matrix-hint">A confirmação ou rejeição registra apenas uma decisão auditável. Não executa operação bancária nem altera saldos, obrigações ou settlement.</p><div v-if="loadingSuggestions" class="cb-empty-state"><v-progress-circular indeterminate size="24" /><p>Buscando candidatos seguros…</p></div><p v-else-if="suggestionError" class="matrix-hint" role="alert">{{ suggestionError }}</p><p v-else-if="bankSuggestions?.classification === 'NO_MATCH'" class="matrix-hint">Nenhum lançamento bancário elegível foi encontrado para esta execução.</p><div v-else-if="bankSuggestions" class="matrix-scroll"><table class="closing-matrix"><thead><tr><th>Classificação</th><th>Valor</th><th>Data</th><th>Direção</th><th>Explicação</th><th v-if="userStore.isAdmin">Decisão</th></tr></thead><tbody><tr v-for="candidate in bankSuggestions.candidates" :key="candidate.candidateId"><th><v-chip size="x-small" :color="candidate.classification === 'EXACT' ? 'success' : candidate.classification === 'AMBIGUOUS' ? 'warning' : 'info'" variant="tonal">{{ suggestionLabel(candidate.classification) }}</v-chip></th><td>{{ money(candidate.amount) }}</td><td>{{ formatDate(candidate.transactionDate) }}</td><td>{{ candidate.direction === 'OUTFLOW' ? 'Saída' : 'Entrada' }}</td><td><span class="suggestion-reasons">{{ candidate.reasons.map(reasonLabel).join(' · ') }}</span></td><td v-if="userStore.isAdmin"><div class="reconciliation-actions"><v-btn size="small" color="success" :loading="reconciliationActionId === candidate.candidateId" @click="confirmBankSuggestion(candidate)">Confirmar</v-btn><v-btn size="small" variant="tonal" color="error" @click="rejectionCandidateId = candidate.candidateId">Rejeitar</v-btn></div></td></tr></tbody></table></div><div v-if="userStore.isAdmin && rejectionCandidate" class="payment-form reconciliation-rejection"><v-select v-model="rejectionReason" :items="rejectionReasons" label="Motivo da rejeição" /><v-btn color="error" :loading="reconciliationActionId === rejectionCandidate.candidateId" @click="rejectBankSuggestion">Confirmar rejeição</v-btn><v-btn variant="text" @click="rejectionCandidateId = ''">Cancelar</v-btn></div><div v-if="reconciliationHistory.length" class="reconciliation-history"><p class="eyebrow">Histórico seguro</p><ul><li v-for="item in reconciliationHistory" :key="item.id">{{ item.status === 'CONFIRMED' ? 'Correspondência confirmada' : `Sugestão rejeitada: ${rejectionLabel(item.rejectionReasonCode)}` }} · {{ formatDateTime(item.decidedAt) }}</li></ul></div></section>
        <section v-if="summary && matrix && userStore.canWrite && obligations.length" class="cb-card obligations-card"><div class="section-heading"><div><p class="eyebrow">Fato compensatório</p><h2>Correção financeira</h2></div></div><p class="matrix-hint">A reversão apenas reabre o efeito derivado de uma alocação conciliada. Não executa transferência nem modifica os fatos históricos.</p><div class="payment-form"><v-select v-model="correctionType" :items="correctionTypes" label="Efeito" /><v-select v-model="correctionObligationId" :items="obligations.map(item => ({ title: `${item.domain} · ${money(item.openAmount)}`, value: item.id }))" label="Obrigação de origem" /><v-text-field v-model.number="correctionAmount" label="Valor" type="number" min="0.01" /><template v-if="isSettlementReversal"><v-text-field v-model="reversalAllocationId" label="ID da alocação original" /><v-text-field v-model="reversalTransactionId" label="ID seguro do retorno bancário" /><v-text-field v-model="reversalReasonCode" label="Motivo tipado" /></template><v-btn color="primary" :disabled="!canCreateCorrection" @click="createCorrection">Criar para revisão</v-btn></div><div v-if="correction"><p class="matrix-hint">{{ correction.type }} · {{ correction.status }}<template v-if="correction.rejectionReasonCode"> · {{ correction.rejectionReasonCode }}</template></p><div class="payment-form"><v-btn v-if="correction.status === 'DRAFT'" @click="submitCorrection">Enviar para revisão</v-btn><v-btn v-if="correction.status === 'REVIEW' && userStore.isAdmin" color="success" @click="approveCorrection">Aprovar fato compensatório</v-btn><v-btn v-if="correction.status === 'REVIEW' && userStore.isAdmin" color="error" variant="tonal" @click="rejectCorrection">Rejeitar</v-btn></div></div></section>
        <section v-if="summary && matrix && settlementReversal" class="cb-card obligations-card"><p class="eyebrow">Histórico seguro da reversão</p><p class="matrix-hint">Fato emitido · {{ money(settlementReversal.amount) }} · {{ settlementReversal.reasonCode }} · {{ formatDateTime(settlementReversal.approvedAt) }}</p></section>
        <div v-if="!summary || !matrix" class="cb-empty-state"><v-icon size="40">mdi-calculator-variant-outline</v-icon><p class="cb-empty-state__title">Importe os itens e calcule a apuração</p><p>As fontes tabulares confirmadas invalidam o cálculo anterior até uma nova apuração.</p></div>
      </template>
    </div>

    <v-dialog v-model="drillOpen" max-width="860">
      <v-card><v-card-title>{{ drillTitle }}</v-card-title><v-card-subtitle v-if="drill">Bruto {{ money(drill.grossAmount) }} · Deduções {{ money(drill.deductionAmount) }} · Ajustes {{ signedMoney(drill.adjustmentAmount) }} · Líquido {{ money(drill.netAmount) }}</v-card-subtitle>
        <v-card-text><v-progress-linear v-if="loadingDrill" indeterminate /><div v-else-if="drill" class="drill-list"><article v-for="item in drill.items" :key="item.itemId"><div><strong>{{ item.financialLabel || item.clientItemKey }}</strong><small>{{ item.occurredOn || 'Data não informada' }}</small></div><div><span>{{ money(item.signedGrossAmount) }}</span><span>− {{ money(item.deductionAmount) }}</span><strong>{{ money(item.netAmount) }}</strong></div></article></div></v-card-text>
        <v-card-actions><v-spacer /><v-btn @click="drillOpen = false">Fechar</v-btn></v-card-actions></v-card>
    </v-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import FinancialClosingService, { type BankReconciliation, type BankReconciliationCandidate, type BankReconciliationSuggestionPage, type CalculationMemory, type CalculationRevision, type ClosingMatrix, type ClosingSource, type ClosingSummary, type DrillDown, type FinancialClosing, type MatrixRow, type OperationalObligation, type PaymentExecution, type FinancialCorrection, type SettlementReversal, type TabularImportMapping, type TabularImportValidation, type PayoutDecision, type MarginDecision, type ClosingOperations, type TabularImportExecution, type TabularImportIssuePage } from '@/services/FinancialClosingService'
import { useUserStore } from '@/plugins/userStore'
import PageHeader from '@/components/PageHeader.vue'
import AlertStrip from '@/components/AlertStrip.vue'

const userStore = useUserStore()
const closings = ref<FinancialClosing[]>([]); const selectedId = ref(''); const summary = ref<ClosingSummary | null>(null); const matrix = ref<ClosingMatrix | null>(null)
const memory = ref<CalculationMemory | null>(null); const drill = ref<DrillDown | null>(null); const drillOpen = ref(false)
const obligations = ref<OperationalObligation[]>([]); const loadingObligations = ref(false); const obligationDomain = ref('ALL')
const paymentAmount = ref<number | null>(null); const paymentReference = ref(''); const paymentExecutedAt = ref(''); const savingPayment = ref(false); const recordedPayment = ref<PaymentExecution | null>(null); const confirmationJustification = ref(''); const confirmationEvidence = ref('')
const suggestionPaymentId = ref(''); const bankSuggestions = ref<BankReconciliationSuggestionPage | null>(null); const reconciliationHistory = ref<BankReconciliation[]>([]); const loadingSuggestions = ref(false); const suggestionError = ref(''); const reconciliationActionId = ref(''); const rejectionCandidateId = ref(''); const rejectionReason = ref('NOT_SAME_PAYMENT'); const rejectionReasons = [{ title: 'Não é o mesmo pagamento', value: 'NOT_SAME_PAYMENT' }, { title: 'Lançamento bancário duplicado', value: 'DUPLICATE_BANK_ENTRY' }, { title: 'Data incompatível', value: 'DATE_MISMATCH' }, { title: 'Valor incompatível', value: 'AMOUNT_MISMATCH' }, { title: 'Exige revisão manual', value: 'MANUAL_REVIEW_REQUIRED' }]
const correctionType = ref('RELEASE_OPEN_PRINCIPAL'); const correctionObligationId = ref(''); const correctionAmount = ref<number | null>(null); const reversalAllocationId = ref(''); const reversalTransactionId = ref(''); const reversalReasonCode = ref('BANK_RETURN'); const correction = ref<FinancialCorrection | null>(null); const settlementReversal = ref<SettlementReversal | null>(null); const correctionTypes = [{ title: 'Crédito contra principal aberto', value: 'RELEASE_OPEN_PRINCIPAL' }, { title: 'Obrigação complementar', value: 'ISSUE_SUPPLEMENT' }, { title: 'Obrigação de recuperação', value: 'ISSUE_RECOVERY' }, { title: 'Reversão de alocação conciliada', value: 'REVERSE_SETTLEMENT_ALLOCATION' }]
const tabularFile = ref<File | File[] | null>(null); const tabularBatchKey = ref(`TABULAR-${new Date().toISOString().slice(0, 10)}`); const tabularValidating = ref(false); const tabularConfirming = ref(false); const tabularMessage = ref(''); const tabularValidation = ref<TabularImportValidation | null>(null)
const tabularMapping = ref<TabularImportMapping>({ itemKeyColumn: 'itemKey', sourceIdColumn: 'sourceId', amountColumn: 'amount', occurredOnColumn: 'occurredOn', attributionMethodColumn: 'attributionMethod', participantIdColumn: 'participantId', poolKeyColumn: 'poolKey', defaultAttributionMethod: 'DIRECT_ATTRIBUTION', decimalSeparator: 'DOT' })
const operations = ref<ClosingOperations | null>(null); const importExecutions = ref<TabularImportExecution[]>([]); const importIssues = ref<TabularImportIssuePage | null>(null); const loadingOperations = ref(false)
const calculationRevisions = ref<CalculationRevision[]>([]); const payoutDecisions = ref<PayoutDecision[]>([]); const marginDecisions = ref<MarginDecision[]>([]); const payoutDecision = ref<PayoutDecision | null>(null); const loadingDecisionData = ref(false); const creatingPayout = ref(false); const payoutDueDate = ref(''); const payoutApprovalJustification = ref(''); const marginApprovalJustification = ref('')
const marginPoolKey = ref('MARGEM_CONTRIBUICAO'); const marginAllocationType = ref('RETAIN'); const marginAmount = ref<number | null>(null); const marginPurpose = ref(''); const marginBeneficiaryName = ref(''); const marginParticipantId = ref(''); const marginAllocationTypes = [{ title: 'Resultado retido', value: 'RETAIN' }, { title: 'Reserva', value: 'RESERVE' }, { title: 'Compromisso de despesa', value: 'EXPENSE_COMMITMENT' }, { title: 'Distribuição', value: 'DISTRIBUTE' }]
const loading = ref(true); const calculating = ref(false); const loadingMemory = ref(false); const loadingDrill = ref(false); const errorMessage = ref(''); const drillTitle = ref('Detalhamento')
const selectedClosing = computed(() => closings.value.find(item => item.id === selectedId.value) || null)
const selectedTabularFile = computed(() => Array.isArray(tabularFile.value) ? tabularFile.value[0] || null : tabularFile.value)
const canConfirmTabularImport = computed(() => Boolean(userStore.isAdmin && selectedClosing.value && selectedTabularFile.value && tabularBatchKey.value.trim() && tabularValidation.value?.valid))
const marginNeedsBeneficiary = computed(() => marginAllocationType.value === 'EXPENSE_COMMITMENT' || marginAllocationType.value === 'DISTRIBUTE')
const canCreateMarginDecision = computed(() => Boolean(userStore.canWrite && marginPoolKey.value.trim() && marginPurpose.value.trim() && marginAmount.value && marginAmount.value > 0 && (!marginNeedsBeneficiary.value || marginBeneficiaryName.value.trim()) && (marginAllocationType.value !== 'DISTRIBUTE' || marginParticipantId.value.trim())))
const closingOptions = computed(() => closings.value.map(item => ({ value: item.id, title: `${String(item.periodMonth).padStart(2, '0')}/${item.periodYear} · ${item.closingKey}` })))
const workflowLabel = computed(() => ({ DRAFT: 'Rascunho', REVIEW: 'Em revisão', APPROVED: 'Aprovado', CANCELLED: 'Cancelado' }[selectedClosing.value?.workflowStatus || 'DRAFT']))
const canCalculate = computed(() => userStore.canWrite && selectedClosing.value?.workflowStatus === 'DRAFT' && selectedClosing.value.currentVersion.versionStatus === 'EDITABLE')
const headerSummary = computed(() => summary.value ? [{ label: 'Produtividade Líquida', value: money(summary.value.productivityAmount) }, { label: 'Margem separada', value: money(summary.value.undistributedPoolAmount) }, { label: 'Receita líquida', value: money(summary.value.netRevenueAmount) }] : [])
const filteredObligations = computed(() => obligations.value.filter(item => obligationDomain.value === 'ALL' || item.domain === obligationDomain.value))
const rejectionCandidate = computed(() => bankSuggestions.value?.candidates.find(candidate => candidate.candidateId === rejectionCandidateId.value) || null)
const isSettlementReversal = computed(() => correctionType.value === 'REVERSE_SETTLEMENT_ALLOCATION')
const canCreateCorrection = computed(() => Boolean(correctionObligationId.value && correctionAmount.value && (!isSettlementReversal.value || (reversalAllocationId.value && reversalTransactionId.value && reversalReasonCode.value))))
const money = (value: number | undefined) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: selectedClosing.value?.currency || 'BRL' }).format(Number(value || 0))
const signedMoney = (value: number) => `${value > 0 ? '+' : ''}${money(value)}`
const decisionStatusLabel = (status: string) => ({ DRAFT: 'Rascunho', REVIEW: 'Em revisão', APPROVED: 'Aprovada', REJECTED: 'Rejeitada' } as Record<string, string>)[status] || status
const marginTypeLabel = (type: string) => ({ RETAIN: 'Resultado retido', RESERVE: 'Reserva', EXPENSE_COMMITMENT: 'Compromisso de despesa', DISTRIBUTE: 'Distribuição' } as Record<string, string>)[type] || type

async function loadClosings() { loading.value = true; errorMessage.value = ''; try { const { data } = await FinancialClosingService.list(); closings.value = data; if (!selectedId.value && data.length) selectedId.value = data[0].id; if (!data.length) loading.value = false } catch { errorMessage.value = 'Não foi possível carregar as apurações.'; loading.value = false } }
async function loadResult() { const closing = selectedClosing.value; if (!closing) return; loading.value = true; memory.value = null; errorMessage.value = ''; try { const [summaryResponse, matrixResponse] = await Promise.all([FinancialClosingService.summary(closing), FinancialClosingService.matrix(closing)]); summary.value = summaryResponse.data; matrix.value = matrixResponse.data } catch (error: any) { summary.value = null; matrix.value = null; errorMessage.value = error?.response?.status === 409 ? 'Os dados mudaram e o cálculo precisa ser refeito.' : 'Não foi possível carregar o resultado da apuração.' } finally { loading.value = false } }
async function loadObligations() { loadingObligations.value = true; try { obligations.value = (await FinancialClosingService.obligations()).data } catch { obligations.value = [] } finally { loadingObligations.value = false } }
async function loadOperations() { const closing=selectedClosing.value; if(!closing)return; loadingOperations.value=true; importIssues.value=null; try { const [operationsResponse,importsResponse]=await Promise.all([FinancialClosingService.operations(closing),FinancialClosingService.tabularImportExecutions(closing)]); operations.value=operationsResponse.data; importExecutions.value=importsResponse.data.items } catch { operations.value=null; importExecutions.value=[]; errorMessage.value='Não foi possível carregar a central operacional.' } finally { loadingOperations.value=false } }
async function loadImportIssues(id:string) { const closing=selectedClosing.value; if(!closing)return; try { importIssues.value=(await FinancialClosingService.tabularImportIssues(closing,id)).data } catch { errorMessage.value='Não foi possível consultar os erros seguros da importação.' } }
async function validateTabularImport() { const closing = selectedClosing.value; const file = selectedTabularFile.value; if (!closing || !file) return; tabularValidating.value = true; tabularMessage.value = ''; try { const response = await FinancialClosingService.validateTabularImport(closing, file, tabularMapping.value); tabularValidation.value = response.data; tabularMessage.value = response.data.valid ? 'Arquivo válido. Revise os totais antes de confirmar o lote.' : 'O arquivo possui erros e não pode ser confirmado.' } catch (error: any) { tabularValidation.value = error?.response?.data?.issues ? error.response.data : null; tabularMessage.value = 'Não foi possível validar a planilha. Confira o arquivo e o mapeamento.' } finally { tabularValidating.value = false } }
async function confirmTabularImport() { const closing = selectedClosing.value; const file = selectedTabularFile.value; if (!closing || !file || !tabularValidation.value?.valid) return; tabularConfirming.value = true; tabularMessage.value = ''; try { const response = await FinancialClosingService.confirmTabularImport(closing, file, tabularBatchKey.value.trim(), tabularMapping.value); tabularMessage.value = response.data.replayed ? 'Este lote já havia sido confirmado; o resultado original foi reutilizado.' : 'Lote normalizado confirmado. Recalcule a apuração para atualizar os resultados.'; await loadClosings(); selectedId.value = closing.id; summary.value = null; matrix.value = null } catch (error: any) { if (error?.response?.data?.issues) { tabularValidation.value = error.response.data; tabularMessage.value = 'A confirmação foi bloqueada pelos erros de validação.' } else tabularMessage.value = error?.response?.status === 403 ? 'A confirmação exige ADMIN/OWNER com concessão explícita aos dados sensíveis.' : 'Não foi possível confirmar o lote.' } finally { tabularConfirming.value = false } }
async function loadDecisionData() { const closing = selectedClosing.value; if (!closing) return; loadingDecisionData.value = true; try { const [revisions, payouts, margins] = await Promise.all([FinancialClosingService.calculationRevisions(closing), FinancialClosingService.payoutDecisions(closing), FinancialClosingService.marginDecisions(closing)]); calculationRevisions.value = revisions.data; payoutDecisions.value = payouts.data; marginDecisions.value = margins.data; payoutDecision.value = payouts.data.find(item => item.status !== 'APPROVED') || payouts.data[0] || null } catch { errorMessage.value = 'Não foi possível carregar as revisões e decisões.' } finally { loadingDecisionData.value = false } }
async function createPayoutDecision() { const closing = selectedClosing.value; if (!closing) return; creatingPayout.value = true; try { payoutDecision.value = (await FinancialClosingService.createPayoutDecision(closing, payoutDueDate.value || undefined)).data; await loadDecisionData() } catch { errorMessage.value = 'Não foi possível criar a proposta de repasse. Confirme que o cálculo atual está conciliado.' } finally { creatingPayout.value = false } }
async function submitPayoutDecision() { const closing = selectedClosing.value; if (!closing || !payoutDecision.value) return; try { payoutDecision.value = (await FinancialClosingService.submitPayoutDecision(closing, payoutDecision.value.id, payoutDecision.value.revision)).data; await loadClosings(); selectedId.value = closing.id } catch { errorMessage.value = 'Não foi possível enviar a proposta para revisão.' } }
async function approvePayoutDecision() { const closing = selectedClosing.value; if (!closing || !payoutDecision.value) return; try { payoutDecision.value = (await FinancialClosingService.approvePayoutDecision(closing, payoutDecision.value.id, payoutDecision.value.revision, payoutApprovalJustification.value)).data; await Promise.all([loadClosings(), loadObligations(), loadDecisionData()]); selectedId.value = closing.id } catch { errorMessage.value = 'Não foi possível aprovar a proposta. A aprovação exige um aprovador elegível e conciliação integral.' } }
async function createMarginDecision() { const closing = selectedClosing.value; if (!closing || !canCreateMarginDecision.value || !marginAmount.value) return; const type = marginAllocationType.value; const beneficiary = type === 'EXPENSE_COMMITMENT' ? { type: 'EXTERNAL_CREDITOR', displayName: marginBeneficiaryName.value.trim(), externalReference: `ui:${marginBeneficiaryName.value.trim()}` } : undefined; const beneficiaries = type === 'DISTRIBUTE' ? [{ clientBeneficiaryKey: marginParticipantId.value.trim(), amount: marginAmount.value, beneficiary: { type: 'CLOSING_PARTICIPANT', closingParticipantId: marginParticipantId.value.trim(), displayName: marginBeneficiaryName.value.trim() } }] : undefined; try { await FinancialClosingService.createMarginDecision(closing, { poolKey: marginPoolKey.value.trim(), allocations: [{ type, amount: marginAmount.value, purpose: marginPurpose.value.trim(), beneficiary, beneficiaries }] }); await loadDecisionData() } catch { errorMessage.value = 'Não foi possível criar a proposta de margem. Revise a capacidade do pool e o beneficiário.' } }
async function submitMarginDecision(decision: MarginDecision) { const closing = selectedClosing.value; if (!closing) return; try { await FinancialClosingService.submitMarginDecision(closing, decision.id, decision.revision); await loadDecisionData() } catch { errorMessage.value = 'Não foi possível enviar a destinação de margem para revisão.' } }
async function approveMarginDecision(decision: MarginDecision) { const closing = selectedClosing.value; if (!closing) return; try { await FinancialClosingService.approveMarginDecision(closing, decision.id, decision.revision, marginApprovalJustification.value); await Promise.all([loadDecisionData(), loadObligations()]) } catch { errorMessage.value = 'Não foi possível aprovar a destinação de margem.' } }
async function recordPayment() { if (!paymentAmount.value || paymentAmount.value <= 0) return; savingPayment.value = true; try { recordedPayment.value = (await FinancialClosingService.recordPayment({ direction: 'OUTBOUND', currency: selectedClosing.value?.currency || 'BRL', amount: paymentAmount.value, externalReference: paymentReference.value || undefined, idempotencyKey: crypto.randomUUID(), executedAt: paymentExecutedAt.value ? new Date(paymentExecutedAt.value).toISOString() : undefined })).data } catch { errorMessage.value = 'Não foi possível registrar o rascunho.' } finally { savingPayment.value = false } }
async function confirmPayment() { if (!recordedPayment.value) return; try { const paymentId = recordedPayment.value.id; await FinancialClosingService.confirmPayment(paymentId, { justification: confirmationJustification.value, evidenceReference: confirmationEvidence.value, idempotencyKey: crypto.randomUUID() }); recordedPayment.value = null; confirmationEvidence.value = ''; confirmationJustification.value = ''; suggestionPaymentId.value = paymentId; await Promise.all([loadObligations(), loadBankSuggestions()]) } catch { errorMessage.value = 'Não foi possível confirmar o fato interno.' } }
async function voidPayment() { if (!recordedPayment.value) return; try { await FinancialClosingService.voidPayment(recordedPayment.value.id, 'Anulado pelo operador antes da confirmação'); recordedPayment.value = null } catch { errorMessage.value = 'Não foi possível anular o rascunho.' } }
async function loadBankSuggestions() { if (!suggestionPaymentId.value) return; loadingSuggestions.value = true; suggestionError.value = ''; try { const [suggestions, history] = await Promise.all([FinancialClosingService.bankReconciliationSuggestions(suggestionPaymentId.value), FinancialClosingService.bankReconciliationHistory(suggestionPaymentId.value)]); bankSuggestions.value = suggestions.data; reconciliationHistory.value = history.data } catch { bankSuggestions.value = null; reconciliationHistory.value = []; suggestionError.value = 'Não foi possível consultar as sugestões bancárias.' } finally { loadingSuggestions.value = false } }
async function confirmBankSuggestion(candidate: BankReconciliationCandidate) { if (!suggestionPaymentId.value) return; reconciliationActionId.value = candidate.candidateId; suggestionError.value = ''; try { await FinancialClosingService.confirmBankReconciliation(suggestionPaymentId.value, { financialTransactionId: candidate.candidateId, expectedCandidateFingerprint: candidate.candidateFingerprint }, crypto.randomUUID()); await loadBankSuggestions() } catch (error: any) { suggestionError.value = error?.response?.status === 409 ? 'A sugestão ficou obsoleta ou já recebeu uma decisão. Atualize a consulta.' : 'Não foi possível confirmar a correspondência.' } finally { reconciliationActionId.value = '' } }
async function rejectBankSuggestion() { const candidate = rejectionCandidate.value; if (!candidate || !suggestionPaymentId.value) return; reconciliationActionId.value = candidate.candidateId; suggestionError.value = ''; try { await FinancialClosingService.rejectBankReconciliation(suggestionPaymentId.value, { financialTransactionId: candidate.candidateId, expectedCandidateFingerprint: candidate.candidateFingerprint, reasonCode: rejectionReason.value }, crypto.randomUUID()); rejectionCandidateId.value = ''; await loadBankSuggestions() } catch (error: any) { suggestionError.value = error?.response?.status === 409 ? 'A sugestão ficou obsoleta ou já recebeu uma decisão. Atualize a consulta.' : 'Não foi possível rejeitar a sugestão.' } finally { reconciliationActionId.value = '' } }
async function createCorrection() { if (!canCreateCorrection.value || !correctionAmount.value) return; try { correction.value = (await FinancialClosingService.createCorrection({ type: correctionType.value, originalObligationId: correctionObligationId.value, amount: correctionAmount.value, ...(isSettlementReversal.value ? { originalAllocationId: reversalAllocationId.value, reversalFinancialTransactionId: reversalTransactionId.value, reasonCode: reversalReasonCode.value } : {}) })).data } catch { errorMessage.value = 'Não foi possível criar a correção.' } }
async function submitCorrection() { if (!correction.value) return; try { correction.value = (await FinancialClosingService.submitCorrection(correction.value.id, correction.value.revision)).data } catch { errorMessage.value = 'Não foi possível enviar a correção.' } }
async function approveCorrection() { if (!correction.value) return; try { correction.value = (await FinancialClosingService.approveCorrection(correction.value.id, correction.value.revision)).data; if (correction.value.type === 'REVERSE_SETTLEMENT_ALLOCATION') settlementReversal.value = (await FinancialClosingService.settlementReversal(correction.value.id)).data; await loadObligations() } catch { errorMessage.value = 'Não foi possível aprovar a correção.' } }
async function rejectCorrection() { if (!correction.value) return; try { correction.value = (await FinancialClosingService.rejectCorrection(correction.value.id, correction.value.revision, 'RETURN_NOT_ACCEPTED')).data } catch { errorMessage.value = 'Não foi possível rejeitar a correção.' } }
async function calculate() { const closing = selectedClosing.value; if (!closing) return; calculating.value = true; try { await FinancialClosingService.calculate(closing); await loadClosings(); selectedId.value = closing.id; await loadResult() } catch { errorMessage.value = 'Não foi possível recalcular a apuração.' } finally { calculating.value = false } }
async function toggleMemory() { if (memory.value) { memory.value = null; return } const closing = selectedClosing.value; if (!closing) return; loadingMemory.value = true; try { memory.value = (await FinancialClosingService.memory(closing)).data } finally { loadingMemory.value = false } }
async function openDrillDown(row: MatrixRow, source: ClosingSource) { const closing = selectedClosing.value; if (!closing) return; drillTitle.value = `${row.participant.displayName} · ${source.displayName}`; drillOpen.value = true; loadingDrill.value = true; drill.value = null; try { drill.value = (await FinancialClosingService.drillDown(closing, row.participant.id, source.id)).data } finally { loadingDrill.value = false } }
function prettyMemory(raw: string) { try { return JSON.stringify(JSON.parse(raw), null, 2) } catch { return raw } }
function statusLabel(status: string) { return ({ OPEN: 'Aberto', PARTIAL: 'Parcial', PAID: 'Pago em dinheiro', SETTLED: 'Resolvido por crédito', NOT_APPLICABLE: 'Não aplicável' } as Record<string,string>)[status] || status }
function suggestionLabel(status: string) { return ({ EXACT: 'Correspondência exata', LIKELY: 'Correspondência provável', AMBIGUOUS: 'Revisão manual', NO_MATCH: 'Sem correspondência' } as Record<string,string>)[status] || status }
function reasonLabel(reason: string) { return ({ WORKSPACE_MATCH: 'mesmo espaço', DIRECTION_MATCH: 'direção compatível', AMOUNT_EXACT: 'valor exato', DATE_WINDOW_MATCH: 'data próxima', REFERENCE_HMAC_MATCH: 'referência compatível', UNLINKED_IN_V19_A: 'sem vínculo prévio' } as Record<string,string>)[reason] || reason }
function formatDate(value: string) { return new Intl.DateTimeFormat('pt-BR').format(new Date(`${value}T12:00:00`)) }
function formatDateTime(value: string) { return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) }
function rejectionLabel(reason?: string | null) { return ({ NOT_SAME_PAYMENT: 'não é o mesmo pagamento', DUPLICATE_BANK_ENTRY: 'lançamento duplicado', DATE_MISMATCH: 'data incompatível', AMOUNT_MISMATCH: 'valor incompatível', MANUAL_REVIEW_REQUIRED: 'revisão manual' } as Record<string, string>)[reason || ''] || 'motivo registrado' }
watch(selectedId, () => { loadResult(); loadOperations() }); onMounted(async () => { await loadClosings(); await Promise.all([loadObligations(),loadOperations()]) })
</script>

